  play:(bytes,{signal,cue,voice})=>playSpeechBuffer(audioContext(),bytes,{signal,volume:voice.volume,effect:voice.effect,onLevel:level=>document.dispatchEvent(new CustomEvent('ruby-speech-level',{detail:level})),pauseMs:cue?.pauseMs||0,onStart:()=>{voice.onAudio?.();if(cue)onCue(cue);onSpeaking(true);el('voice-status').textContent='Speaking · offline VoiceM';}})
